-- v34b: namų purškikliai 250 ml (11 kvapų) - kvapai iš esamų scents (originalai, natos, šeima, lytis, spalvos), nuotraukos img/purskikliai/.
-- Aprašymo šablonas: „Namų purškiklis X - {charakteris} aromatas jūsų namams akimirksniu. Viršutinės natos…, širdies…, bazinės…. Užtenka 1-2 purškimų… {nuotaika}.“
insert into public.products (id, name, type, scent_id, conc, gender, family, tagline, description, notes, longevity, sillage, sizes, sample, look, badge, rank, stock, images, visible, inspired, inspired_image, attrs, i18n) values
('namu-purskiklis-goodore', 'Namų purškiklis GOODORE', 'purskikliai', 'goodore', 'EDP', 'moterims', 'ambros', 'Migdolai, tuberozė ir kakava', 'Namų purškiklis GOODORE - gundantis, šiltas gėlių ir kakavos aromatas jūsų namams akimirksniu. Viršutinės natos - migdolai, kava ir bergamotė, širdies - tuberozė, jazminas ir apelsinmedžio žiedai, bazinės - tonkos pupelės, kakava ir vanilė. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Namai prisipildo šilumos ir paslapties.', '{"top": ["Migdolai", "Kava", "Bergamotė"], "heart": ["Tuberozė", "Jazminas", "Apelsinmedžio žiedai"], "base": ["Tonkos pupelės", "Kakava", "Vanilė"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#f6ede1", "shape": "rect", "liquid": "#d49a57"}'::jsonb, 'Naujiena', 60, null, array['img/purskikliai/goodore.jpg'], true, 'Carolina Herrera - Good Girl', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/goodore/mwvhehlp-7sp6b.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray GOODORE", "tagline": "Almond, tuberose and cocoa", "description": "Room spray GOODORE - a seductive, warm floral and cocoa fragrance for your home, instantly. Top notes of almond, coffee and bergamot; a heart of tuberose, jasmine and orange blossom; a base of tonka bean, cocoa and vanilla. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Fills your home with warmth and mystery.", "badge": "New"}}'::jsonb),
('namu-purskiklis-cledore', 'Namų purškiklis CLEDORE', 'purskikliai', 'cledore', 'EDP', 'moterims', 'geliu', 'Bijūnas, ličiai ir pudrinė rožė', 'Namų purškiklis CLEDORE - švelnus, pudrinis rožių aromatas jūsų namams akimirksniu. Viršutinės natos - bijūnas, ličiai ir frezija, širdies - rožė, pakalnutė ir magnolija, bazinės - gintaras ir kedras. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Kuria ramią, švarią ir moterišką erdvės nuotaiką.', '{"top": ["Bijūnas", "Ličiai", "Frezija"], "heart": ["Rožė", "Pakalnutė", "Magnolija"], "base": ["Gintaras", "Kedras"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#faeef0", "shape": "rect", "liquid": "#efc3cb"}'::jsonb, 'Naujiena', 61, null, array['img/purskikliai/cledore.jpg'], true, 'Chloé - Eau de Parfum', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/cledore/mwvhe3kh-hgn9f.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray CLEDORE", "tagline": "Peony, lychee and powdery rose", "description": "Room spray CLEDORE - a soft, powdery rose fragrance for your home, instantly. Top notes of peony, lychee and freesia; a heart of rose, lily of the valley and magnolia; a base of amber and cedar. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Creates a calm, clean and feminine atmosphere.", "badge": "New"}}'::jsonb),
('namu-purskiklis-jadore', 'Namų purškiklis JADORE', 'purskikliai', 'jadore', 'EDP', 'moterims', 'geliu', 'Kriaušė, ilang ilangas ir jazminas', 'Namų purškiklis JADORE - prabangus vaisių ir gėlių aromatas jūsų namams akimirksniu. Viršutinės natos - kriaušė, persikas ir mandarinas, širdies - ilang ilangas, jazminas ir rožė, bazinės - vanilė, muskusas ir kedras. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Namai prisipildo šviesos ir švelnios elegancijos.', '{"top": ["Kriaušė", "Persikas", "Mandarinas"], "heart": ["Ilang ilangas", "Jazminas", "Rožė"], "base": ["Vanilė", "Muskusas", "Kedras"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#faeef0", "shape": "rect", "liquid": "#efc3cb"}'::jsonb, 'Naujiena', 62, null, array['img/purskikliai/jadore.jpg'], true, 'Dior - J''adore', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/jadore/mwvhn5fm-nvi1c.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray JADORE", "tagline": "Pear, ylang-ylang and jasmine", "description": "Room spray JADORE - a luxurious fruity-floral fragrance for your home, instantly. Top notes of pear, peach and mandarin; a heart of ylang-ylang, jasmine and rose; a base of vanilla, musk and cedar. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Fills your home with light and gentle elegance.", "badge": "New"}}'::jsonb),
('namu-purskiklis-nifodore', 'Namų purškiklis NIFODORE', 'purskikliai', 'nifodore', 'EDP', 'moterims', 'geliu', 'Aldehidai, rožė ir jazminas', 'Namų purškiklis NIFODORE - klasikinis, pudrinis gėlių aromatas jūsų namams akimirksniu. Viršutinės natos - aldehidai, nerolis ir bergamotė, širdies - rožė, jazminas ir ilang ilangas, bazinės - santalas ir vanilė. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Kuria elegantišką, nesenstančią nuotaiką.', '{"top": ["Aldehidai", "Nerolis", "Bergamotė"], "heart": ["Rožė", "Jazminas", "Ilang ilangas"], "base": ["Santalas", "Vanilė"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#faeef0", "shape": "rect", "liquid": "#efc3cb"}'::jsonb, 'Naujiena', 63, null, array['img/purskikliai/nifodore.jpg'], true, 'Chanel - N°5', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/nifodore/mwvhqn6l-fs2db.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray NIFODORE", "tagline": "Aldehydes, rose and jasmine", "description": "Room spray NIFODORE - a classic, powdery floral fragrance for your home, instantly. Top notes of aldehydes, neroli and bergamot; a heart of rose, jasmine and ylang-ylang; a base of sandalwood and vanilla. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Creates an elegant, timeless mood.", "badge": "New"}}'::jsonb),
('namu-purskiklis-madore', 'Namų purškiklis MADORE', 'purskikliai', 'madore', 'EDP', 'moterims', 'ambros', 'Apelsinas, rožė ir pačiulis', 'Namų purškiklis MADORE - elegantiškas, gaivus ambros aromatas jūsų namams akimirksniu. Viršutinės natos - apelsinas ir bergamotė, širdies - rožė ir jazminas, bazinės - pačiulis ir vetiveris. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Namai prisipildo elegancijos ir šviežumo.', '{"top": ["Apelsinas", "Bergamotė"], "heart": ["Rožė", "Jazminas"], "base": ["Pačiulis", "Vetiveris"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#f6ede1", "shape": "rect", "liquid": "#d49a57"}'::jsonb, 'Naujiena', 64, null, array['img/purskikliai/madore.jpg'], true, 'Chanel - Coco Mademoiselle', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/madore/mwvhona9-003zw.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray MADORE", "tagline": "Orange, rose and patchouli", "description": "Room spray MADORE - an elegant, fresh amber fragrance for your home, instantly. Top notes of orange and bergamot; a heart of rose and jasmine; a base of patchouli and vetiver. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Fills your home with elegance and freshness.", "badge": "New"}}'::jsonb),
('namu-purskiklis-millidore', 'Namų purškiklis MILLIDORE', 'purskikliai', 'millidore', 'EDP', 'vyrams', 'ambros', 'Mandarinas, cinamonas ir oda', 'Namų purškiklis MILLIDORE - šiltas, pikantiškas mandarinų ir odos aromatas jūsų namams akimirksniu. Viršutinės natos - raudonasis mandarinas, greipfrutas ir mėta, širdies - rožė, cinamonas ir prieskoniai, bazinės - oda, gintaras, medienos natos ir pačiulis. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Kuria drąsią, šiltą ir išskirtinę nuotaiką.', '{"top": ["Raudonasis mandarinas", "Greipfrutas", "Mėta"], "heart": ["Rožė", "Cinamonas", "Prieskoniai"], "base": ["Oda", "Gintaras", "Medienos natos", "Pačiulis"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#f6ede1", "shape": "rect", "liquid": "#d49a57"}'::jsonb, 'Naujiena', 65, null, array['img/purskikliai/millidore.jpg'], true, 'Paco Rabanne - One Million', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/millidore/mwpg1uks-t3kj6.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray MILLIDORE", "tagline": "Mandarin, cinnamon and leather", "description": "Room spray MILLIDORE - a warm, spicy mandarin and leather fragrance for your home, instantly. Top notes of red mandarin, grapefruit and mint; a heart of rose, cinnamon and spices; a base of leather, amber, woody notes and patchouli. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Creates a bold, warm and distinctive mood.", "badge": "New"}}'::jsonb),
('namu-purskiklis-baccadore', 'Namų purškiklis BACADORE', 'purskikliai', 'baccadore', 'EDP', 'unisex', 'medienos', 'Šafranas, gintaro mediena ir kėnių derva', 'Namų purškiklis BACADORE - prabangus, šiltas šafrano ir gintaro medienos aromatas jūsų namams akimirksniu. Viršutinės natos - šafranas ir jazminas, širdies - gintaro mediena, pilkasis ambra ir hedionas, bazinės - kėnių derva, kedras, cukrus, ambroksanas ir ąžuolo samanos. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Namai prisipildo prabangos ir ramios šilumos.', '{"top": ["Šafranas", "Jazminas"], "heart": ["Gintaro mediena", "Pilkasis ambra", "Hedionas"], "base": ["Kėnių derva", "Kedras", "Cukrus", "Ambroksanas", "Ąžuolo samanos"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#f3ece4", "shape": "rect", "liquid": "#c9a27a"}'::jsonb, 'Naujiena', 66, null, array['img/purskikliai/baccadore.jpg'], true, 'Baccarat Rouge 540', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/baccadore/mwpgzdml-xsdns.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray BACADORE", "tagline": "Saffron, amberwood and fir resin", "description": "Room spray BACADORE - a luxurious, warm saffron and amberwood fragrance for your home, instantly. Top notes of saffron and jasmine; a heart of amberwood, ambergris and hedione; a base of fir resin, cedar, sugar, ambroxan and oakmoss. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Fills your home with luxury and calm warmth.", "badge": "New"}}'::jsonb),
('namu-purskiklis-opiudore', 'Namų purškiklis OPIUDORE', 'purskikliai', 'opiudore', 'EDP', 'moterims', 'gurmaniski', 'Kava, jazminas ir vanilė', 'Namų purškiklis OPIUDORE - sodrus, gurmaniškas kavos ir vanilės aromatas jūsų namams akimirksniu. Viršutinės natos - kriaušė, rožiniai pipirai ir apelsinmedžio žiedai, širdies - kava ir jazminas, bazinės - vanilė, pačiulis ir kedras. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Vakarais kuria šiltą, gundančią nuotaiką.', '{"top": ["Kriaušė", "Rožiniai pipirai", "Apelsinmedžio žiedai"], "heart": ["Kava", "Jazminas"], "base": ["Vanilė", "Pačiulis", "Kedras"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#f5ece6", "shape": "rect", "liquid": "#b98a6a"}'::jsonb, 'Naujiena', 67, null, array['img/purskikliai/opiudore.jpg'], true, 'Yves Saint Laurent - Black Opium', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/opiudore/mwvh37a1-h6iqc.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray OPIUDORE", "tagline": "Coffee, jasmine and vanilla", "description": "Room spray OPIUDORE - a rich, gourmand coffee and vanilla fragrance for your home, instantly. Top notes of pear, pink pepper and orange blossom; a heart of coffee and jasmine; a base of vanilla, patchouli and cedar. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Creates a warm, seductive mood in the evening.", "badge": "New"}}'::jsonb),
('namu-purskiklis-waydore', 'Namų purškiklis WAYDORE', 'purskikliai', 'waydore', 'EDP', 'moterims', 'geliu', 'Bergamotė, tuberozė ir vanilė', 'Namų purškiklis WAYDORE - švelnus baltųjų gėlių aromatas jūsų namams akimirksniu. Viršutinės natos - bergamotė ir apelsinmedžio žiedai, širdies - tuberozė ir jazminas, bazinės - vanilė, baltasis muskusas ir kedras. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Kuria šviesią, ramią namų nuotaiką.', '{"top": ["Bergamotė", "Apelsinmedžio žiedai"], "heart": ["Tuberozė", "Jazminas"], "base": ["Vanilė", "Baltasis muskusas", "Kedras"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#fbf0f1", "shape": "rect", "liquid": "#f1c9cf"}'::jsonb, 'Naujiena', 68, null, array['img/purskikliai/waydore.jpg'], true, 'Giorgio Armani - My Way', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/waydore/mwpfnc0s-j5wha.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray WAYDORE", "tagline": "Bergamot, tuberose and vanilla", "description": "Room spray WAYDORE - a soft white-floral fragrance for your home, instantly. Top notes of bergamot and orange blossom; a heart of tuberose and jasmine; a base of vanilla, white musk and cedar. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Creates a bright, calm mood at home.", "badge": "New"}}'::jsonb),
('namu-purskiklis-belladore', 'Namų purškiklis BELLADORE', 'purskikliai', 'belladore', 'EDP', 'moterims', 'gurmaniski', 'Irisas, pralinė ir vanilė', 'Namų purškiklis BELLADORE - saldus, švelnus gurmaniškas aromatas jūsų namams akimirksniu. Viršutinės natos - juodieji serbentai ir kriaušė, širdies - irisas, jazminas ir apelsinmedžio žiedai, bazinės - pralinė, vanilė, tonkos pupelės ir pačiulis. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Namai prisipildo džiaugsmo ir jaukumo.', '{"top": ["Juodieji serbentai", "Kriaušė"], "heart": ["Irisas", "Jazminas", "Apelsinmedžio žiedai"], "base": ["Pralinė", "Vanilė", "Tonkos pupelės", "Pačiulis"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#f5ece6", "shape": "rect", "liquid": "#b98a6a"}'::jsonb, 'Naujiena', 69, null, array['img/purskikliai/belladore.jpg'], true, 'Lancôme - La Vie Est Belle', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/belladore/mwvhkbap-ezmb5.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray BELLADORE", "tagline": "Iris, praline and vanilla", "description": "Room spray BELLADORE - a sweet, soft gourmand fragrance for your home, instantly. Top notes of blackcurrant and pear; a heart of iris, jasmine and orange blossom; a base of praline, vanilla, tonka bean and patchouli. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Your home fills with joy and cosiness.", "badge": "New"}}'::jsonb),
('namu-purskiklis-sauvadore', 'Namų purškiklis SAUVADORE', 'purskikliai', 'sauvadore', 'EDP', 'vyrams', 'sviezi', 'Bergamotė, levanda ir kedras', 'Namų purškiklis SAUVADORE - gaivus, švarus aromatas jūsų namams akimirksniu. Viršutinės natos - bergamotė ir pipirai, širdies - Sičuano pipirai, levanda ir vetiveris, bazinės - ambroksanas, kedras ir labdanas. Užtenka 1-2 purškimų į orą arba ant užuolaidų, patalynės ir minkštų baldų - kvapas ilgai išlieka ore ir audiniuose. Namuose kvepia lengvai ir švariai, lyg po lietaus.', '{"top": ["Bergamotė", "Pipirai"], "heart": ["Sičuano pipirai", "Levanda", "Vetiveris"], "base": ["Ambroksanas", "Kedras", "Labdanas"]}'::jsonb, 3, 3, '[{"ml": 250, "price": 12.99}]'::jsonb, 0, '{"cap": "gold", "tint": "#eef5f7", "shape": "rect", "liquid": "#cfe4ea"}'::jsonb, 'Naujiena', 70, null, array['img/purskikliai/sauvadore.jpg'], true, 'Dior - Sauvage', 'https://ubtytpfsqbofqizgkxtc.supabase.co/storage/v1/object/public/products/originalai/sauvadore/mwpfyxkd-kceh1.jpg', '{"forTextile": true}'::jsonb, '{"en": {"name": "Room spray SAUVADORE", "tagline": "Bergamot, lavender and cedar", "description": "Room spray SAUVADORE - a fresh, clean fragrance for your home, instantly. Top notes of bergamot and pepper; a heart of Sichuan pepper, lavender and vetiver; a base of ambroxan, cedar and labdanum. One or two sprays into the air or onto curtains, bedding and upholstery are enough - the scent lingers in the air and on fabrics. Your home smells light and clean, like after the rain.", "badge": "New"}}'::jsonb)
on conflict (id) do update set name = excluded.name, type = excluded.type, scent_id = excluded.scent_id, conc = excluded.conc, gender = excluded.gender, family = excluded.family, tagline = excluded.tagline, description = excluded.description, notes = excluded.notes, longevity = excluded.longevity, sillage = excluded.sillage, sizes = excluded.sizes, sample = excluded.sample, look = excluded.look, badge = excluded.badge, rank = excluded.rank, stock = excluded.stock, images = excluded.images, visible = excluded.visible, inspired = excluded.inspired, inspired_image = excluded.inspired_image, attrs = excluded.attrs, i18n = excluded.i18n;

-- Pradžioje - skyrius „Namų purškikliai“ po difuzorių skyriumi (+ EN pavadinimas)
update public.settings set data = jsonb_set(
  jsonb_set(data, '{rails}', (
    select jsonb_agg(x order by ord) from (
      select r as x, (o*10)::int as ord from jsonb_array_elements(data->'rails') with ordinality as t(r,o)
      union all
      select '{"id":"purskikliai","on":true,"line":"Kvapas akimirksniu - ore ir ant audinių","mode":"auto","rule":{"sort":"rank","type":"purskikliai"},"limit":12,"title":"Namų purškikliai"}'::jsonb,
        coalesce((select (o*10+5)::int from jsonb_array_elements(data->'rails') with ordinality as t(r,o) where r->>'id'='vyrams'), 9999)
    ) z)),
  '{i18n,en,rails,purskikliai}', '{"title":"Room sprays","line":"Instant fragrance - in the air and on fabrics"}'::jsonb)
where id = 1 and data ? 'rails' and not exists (select 1 from jsonb_array_elements(data->'rails') r where r->>'id'='purskikliai');
